# Standard library
import uuid

# Third-party
from sqlalchemy import ForeignKey, Integer, Text, func
from sqlalchemy.orm import Mapped, mapped_column

# Local application
from app.core.base import Base, CreatorMixin, TimestampMixin


class ExplorerM2mTrackGear(TimestampMixin, CreatorMixin, Base):
    __tablename__ = "explorer_m2m_track_gear"

    id: Mapped[uuid.UUID] = mapped_column(
        primary_key=True,
        server_default=func.gen_random_uuid(),
        description=(
            "Primary key UUID, auto-generated by the database using "
            "gen_random_uuid()."
        ),
    )
    slot_position: Mapped[int] = mapped_column(
        Integer,
        nullable=False,
        description=(
            "Zero-based ordering position of this gear item within the track."
        ),
    )
    track_id: Mapped[uuid.UUID] = mapped_column(
        ForeignKey("explorer_agg_track.id", ondelete="CASCADE"),
        nullable=False,
        description=(
            "FK to explorer_agg_track with CASCADE delete. The recorded GPS "
            "activity during which this gear was used."
        ),
    )
    gear_id: Mapped[uuid.UUID] = mapped_column(
        ForeignKey("explorer_agg_gear.id", ondelete="CASCADE"),
        nullable=False,
        description=(
            "FK to explorer_agg_gear with CASCADE delete. The gear item used "
            "during this track."
        ),
    )
    notes: Mapped[str | None] = mapped_column(
        Text,
        description=(
            "Free-text notes about this gear usage on the track (e.g. "
            "comfort, issues, recommendations)."
        ),
    )
    points: Mapped[int | None] = mapped_column(
        Integer,
        description=(
            "Gamification points awarded for using this gear item on the "
            "track."
        ),
    )
